// ══════════════════════════════════════════════════════════════
// 刮板工位序列器 — v1.6（协议 v1.6，乒乓握手 + G-code 驱动 + PhotoMode 路由）
// ══════════════════════════════════════════════════════════════
// 对应上位机 Stage: scrape（PLC 变量前缀 scrape）
// 子步 {0, 10, 15, 20, 30, 40, 90}
// 职责：执行拍照刮板全流程（初始化→点样后拍照/展开后拍照→刮取→收集）
//
// 协议要点（v1.6 PhotoMode 路由机制）：
//   - scrape_PhotoMode 控制初始化后的路径选择：
//     0 = 完整刮板模式（默认）：Step 10 → Step 20（展开后拍照+视觉+刮取）
//     1 = 仅 before-photo 模式：Step 10 → Step 15（点样后拍照，乒乓等待后结束）
//   - Step 15 为 before-photo 乒乓等待点：PLC 完成送板后停在 Step 15，
//     等待 PC 侧拍照完成 → 写 scrape_Confirm=TRUE → PLC 归位后 Done
//   - Step 20 为完整刮板乒乓等待点（与 v1.5 一致）
//   - PhotoMode 由 PC 写入，Step 10 路由决策完成后消费归零（不在 Step 0 归零）
//
// v1.5→v1.6 变更：
//   + 新增 scrape_PhotoMode (INT) 变量
//   + 新增 Step 15 (before-photo 乒乓等待)
//   + Step 10 初始化后按 PhotoMode 路由
//   + 子步号扩展为 {0, 10, 15, 20, 30, 40, 90}
//
// 参照 plc_spotting.txt（spotting 工位）模板编写
// ══════════════════════════════════════════════════════════════
//
// ★★★ PLC工程师交付清单 ★★★
// ─────────────────────────────────────────────────────────────
// 交付状态：v1.6 正式交付（2026-05-17）
// 协议版本：v1.6（对应文档 docs/PLC_Unified_Stage_Protocol.md §8）
// Mock 联调：已通过上位机 mock plc_server 联调验证
// ─────────────────────────────────────────────────────────────
// 1. 新增 GVL 变量（必须添加到全局变量表）：
//    scrape_PhotoMode : INT  — 拍照模式选择（0=完整刮板, 1=仅before-photo）
//    其余 scrape_* 变量与 v1.5 一致，见 VAR_GLOBAL 声明
//
// 2. 关键实机集成点（搜索 TODO【实机集成点】）：
//    □ Step 10: 初始化 FB 替换（当前 stepTimer PT:=T#5S 模拟）
//    □ Step 15 Phase A: 送板入拍照位 FB（点样后送板→拍照→回转运位）
//    □ Step 15 归位: 送板回转运位（Confirm 后板需回到转运位待展开）
//    □ Step 20 Phase A: 送板入拍照位 FB（展开后送板→拍照→刮取）
//    □ Step 30: G-code 解析器 + 刮板运动 FB
//    □ Step 40: 机器人取粉末收集器 FB
//
// 3. 关键安全判断（搜索 TODO【逻辑判断】）：
//    □ 急停时停止刮板电机 + 关闭相机触发
//    □ 复位时清空运动指令
//    □ Step 30 安全占位 G-code 识别（"G0 Z10.0\nM2\n" → 跳过刮板）
//    □ 各步骤超时保护
//
// 4. Phase A 门控机制说明：
//    Step 15/20 的 Confirm 上升沿检测带 phaseA_done 门控标志，
//    确保 PLC 完成送板动作后才检测 PC 侧 Confirm 信号，
//    防止 PC 提前写 Confirm 导致板未到位就推进。
//
// 6. 验收检查清单（实机集成后逐项确认）：
//    □ scrape_PhotoMode=0：FSM 轨迹 0→10→20→30→40→0+Done
//    □ scrape_PhotoMode=1：FSM 轨迹 0→10→15→0+Done
//    □ Step 15 乒乓：PC 写 Confirm=TRUE 后 FSM 归位+Done
//    □ Step 20 乒乓：PC 写 Confirm=TRUE 后 FSM 推进到 Step 30
//    □ Phase A 门控：Step 15/20 送板完成前 Confirm 不触发推进
//    □ 安全占位 G-code：Step 30 收到 "G0 Z10.0\nM2\n" 时跳过刮板
//    □ 急停联锁：PLC_EStop=TRUE 时所有动作停止 + Error 置位
//    □ Reset 脉冲：scrape_Reset=TRUE→FALSE 后 Step/Error 清零
//    □ Enable=FALSE 清 Done：上位机拉低 Enable 后 Done 自动归零
// ─────────────────────────────────────────────────────────────
//
// ★★★ 调试期说明 ★★★
// 本文件为调试期简化版，所有 stepTimer 模拟的位置均为实机集成点。
// 标记说明：
//   TODO【实机集成点】— 需替换为真实 FB/IO 调用的占位
//   TODO【逻辑判断】  — 实机必须增加的条件检查/安全守卫
//   当前 stepTimer PT:=T#5S 仅为模拟延时，实机应替换为实际完成条件
// ══════════════════════════════════════════════════════════════

// ── 1. 急停联锁（最高优先级）──
// TODO【逻辑判断】实机急停时应额外执行：
//   - 停止当前正在执行的刮板电机（若有运动控制）
//   - 关闭相机触发信号
//   - 若 Step 30 正在执行 G-code 路径，急停运动轴
IF NOT 急停 THEN
    scrape_Step  := 0;
    scrape_Done  := FALSE;
    scrape_Error := TRUE;
    scrape_Busy  := FALSE;
    confirmLatched  := FALSE;
    confirmRisingEdge := FALSE;
    phaseA_done_15  := FALSE;
    phaseA_done_20  := FALSE;
	刮板拍照真空自动:=FALSE;
	刮板拍照无刷电机自动:=FALSE;
    stepTimer(IN := FALSE, PT := T#0S);
    RETURN;
END_IF

// ── 2. 复位脉冲（用于错误恢复 / 强制清状态）──
// TODO【逻辑判断】实机复位时应额外执行：
//   - 清空刮板电机运动指令
//   - 复位相机触发状态
IF scrape_Reset THEN
    scrape_Step  := 0;
    scrape_Done  := FALSE;
    scrape_Error := FALSE;
    scrape_Busy  := FALSE;
    confirmLatched  := FALSE;
    confirmRisingEdge := FALSE;
    phaseA_done_15  := FALSE;
    phaseA_done_20  := FALSE;
	初始化step:=0;
	拍照step:=0;
	刮板收集step:=0;
	机器人取物料step:=0;
	 scrape_IsLast := FALSE;       // ★ 新增

    stepTimer(IN := FALSE, PT := T#0S);
    RETURN;
END_IF

// ── 3. Enable=FALSE 时清 Done（次周期复位握手）──
//    上位机收到 Done 后会拉低 scrape_Enable，本段确保下一周期 Done 自动归零，
//    避免 Done 残留导致 Step 0 误判。
IF NOT scrape_Enable THEN
    scrape_Done := FALSE;
END_IF

// ── 4. 派生 scrape_Busy（写者唯一：本 POU 是唯一写者，禁止他处赋值）──
scrape_Busy := (scrape_Step >= 10)
            AND (scrape_Step <= 80)
            AND (NOT scrape_Done);

// ── 5. Confirm 上升沿检测（Phase A 门控）──
//    Step 15 / Step 20 乒乓等待期间有效，其余步骤忽略。
//    上升沿 = 当前值为 TRUE 且上一周期为 FALSE。
//
//    ★ Phase A 门控（v1.6.1 修复）★
//    问题：PC 侧 await_stage_step 检测到 Step=15/20 即认为板已到位，会立即写
//          scrape_Confirm=TRUE。但实际上 Step 15/20 入场时 Phase A（送板）尚未完成，
//          phaseA_done_15/20 仍为 FALSE。若每周期无条件更新 confirmLatched，
//          上升沿会被白白消耗——等 Phase A 完成时 confirmRisingEdge 已永远为 FALSE，
//          导致 PLC 卡死在 Step 15/20。
//    修复：仅在 Phase A 完成后才更新 confirmLatched（即"开门"边沿检测），
//          PC 早写的 Confirm=TRUE 会被挂起，等 Phase A 完成后首次进入门控就识别为上升沿。
//    协议契约：PC 端不改，仍按"看到 Step=15/20 即拍照+Confirm"的简洁时序。
IF scrape_Step=15  THEN
    confirmRisingEdge := scrape_Confirm AND (NOT confirmLatched);
    confirmLatched    := scrape_Confirm;
ELSE
    // Phase A 未完成 → 不更新 confirmLatched，保留 PC 早写的 Confirm=TRUE
    confirmRisingEdge := FALSE;
END_IF






// ── 6. 主状态机（刮板序列器，Step 15/20 乒乓握手 + PhotoMode 路由）──
IF MODE_State=1 THEN	
	CASE scrape_Step OF
		0:  // ═══ 空闲：等待 Enable 上升 ═══
			// ★ PhotoMode 不在此归零：消费型变量应在子步内复位，不可在 Step 0 无条件赋值
			//   （否则 PC 写入 PhotoMode=1 后会被 Step 0 每周期覆盖回 0）
			IF scrape_Enable AND (NOT scrape_Done) THEN
				scrape_Step := 10;
				stepTimer(IN := FALSE, PT := T#0S);  // 复位定时器
			END_IF
		10:
			IF scrape_PhotoMode=2 THEN
				scrape_Step := 15;
			ELSE
				A00_initialization_初始化();
				IF Camera_scraper_initialization_OK THEN
					Camera_scraper_initialization_OK:=FALSE;
					scrape_Step := 15;
					拍照工位允许取硅胶板去展开 := FALSE;
				END_IF
			END_IF



		 15: // ═══ before-photo（PhotoMode=1 时经此路径 — 点样后拍照乒乓等待）═══
			// ★ before-photo 乒乓协议 ★
			// PLC 侧：
			//   1. 将硅胶板送至拍照位（送板动作，与 Step 20 Phase A 同理）
			//   2. 送板完成后停在 Step 15，等待 PC 侧 Confirm
			// PC 侧（BeforePhotoStage）：
			//   1. await_stage_step("scrape", 15) — 检测到 Step=15（板已到位信号）
			//   2. 触发相机拍照（保存为 before.jpg，由 CameraService 负责）
			//   3. 写 scrape_Confirm=TRUE → PLC 完成归位
			//
			// 与 Step 20 的区别：
			//   - Step 15 不需要视觉分析 / G-code 下发，仅拍照
			//   - Confirm 后直接归位+Done，不进入刮取流程
			//   - 拍照触发权同 v1.5.1：由上位机 CameraService 负责，PLC 仅执行送板

			// ── Phase A：送板执行 ──
			// TODO【实机集成点】替换 stepTimer 为真实 FB 调用：
			//   Material_camera_送板入拍照位 := TRUE;    // 送板动作
			//   等待 Material_camera_送板完成_OK = TRUE
			//   注意：拍照触发不再由 PLC 执行，改由上位机 CameraService 触发
			// TODO【逻辑判断】实机需判断：
			//   - 相机拍照超时保护
			//   - 相机通信故障 → Step 90
			A10_Material_camera_拍照硅胶板();
			stepTimer(IN := FALSE, PT := T#0S);
			phaseA_done_15 := TRUE;  // 标记送板完成
			IF Photo_preparation_completed_OK THEN
				IF scrape_PhotoMode = 1 THEN    ///只拍照
					scrape_Step := 16;  // before-photo 模式：去 Step 15 拍照
					拍照工位允许取硅胶板去展开:=TRUE;
					刮板拍照定位气缸自动:=FALSE;
				ELSIF scrape_PhotoMode=2 OR scrape_PhotoMode=0 THEN
					scrape_Step := 20;  // 完整刮板模式：去 Step 20 拍照+视觉+刮取
					Photo_preparation_completed_OK:=FALSE;
				END_IF

				scrape_PhotoMode := 0;  // 消费后复位：路由决策完成后清除 PhotoMode/拍照+刮取
			END_IF
		16:
			IF 取拍照硅胶板完成 THEN
				Photo_preparation_completed_OK:=FALSE;
				取拍照硅胶板完成:=FALSE;
				scrape_Done := TRUE;
				scrape_Step := 0;
			END_IF

				// ── Phase B：乒乓等待 — 仅送板完成后检测 Confirm 上升沿 ──
				// PC 侧拍照完成 → 写 Confirm=TRUE → PLC 归位并结束
// 				IF phaseA_done_15 AND confirmRisingEdge THEN
// 					// PC 侧确认：拍照完成
// 					// 消费 Confirm 信号 + 复位 PhotoMode
// 					scrape_Confirm := FALSE;  // PLC 侧消费 Confirm 信号
// 					confirmLatched := FALSE;  // 复位边沿检测，防止下一周期误触发
// 					phaseA_done_15 := FALSE;  // 复位 Phase A 标志
// 					// TODO【实机集成点】归位动作：将板从拍照位送回转运位（待展开）
// 					//   Material_camera_送板回转运位 := TRUE;
// 					//   等待 Material_camera_回位完成_OK = TRUE
// 					// 当前调试期直接归位完成
// 					scrape_Done := TRUE;
// 					scrape_Busy := FALSE;
// 					scrape_Step := 0;
// 				END_IF



		20: // ═══ 刮取（消费 scrape_gcode_instructions，按 G-code 路径刮板）═══
			// 对应 ref_plc_scraping.txt Step 20: Scraper_collection_刮板收集()
			// 区别：旧版为固定路径刮取，新版由 G-code 驱动灵活路径
			//
			// ★ 视觉失败继续场景 ★
			// 当 PC 侧视觉分析失败但用户选择继续时，PC 会下发安全占位 G-code：
			//   "G0 Z10.0\nM2\n"（Z轴抬至安全位 + 程序结束）
			// PLC 工程师应在 Step 30 中识别此占位指令：
			//   - 方案 A：G-code 解析器遇到 M2 时直接跳过刮板动作，推进到 Step 40
			//   - 方案 B：检查 scrape_gcode_instructions 是否以 "G0 Z" 开头，
			//             若为占位指令则跳过刮板（不驱动电机），仅延时后推进
			// 此场景下流程应正常走到 Step 40（机器人取粉末）+ Done=TRUE，
			// 不执行实际刮板动作，但保证 FSM 完整走完。
			//
			// TODO【实机集成点】替换 stepTimer 为真实 FB 调用：
			//   1. 解析 scrape_gcode_instructions 中的 G-code 指令
			//   2. 按指令序列驱动刮板电机执行运动路径
			//      方案 A：CNC 插补器 FB 逐行消费 G-code
			//      方案 B：上位机预生成运动参数，PLC 直接消费坐标序列
			//   3. 等待运动完成信号（CNC_Done / 刮板到位传感器）
			// TODO【逻辑判断】实机需判断：
			//   - G-code 解析错误 → Step 90 故障
			//   - 刮板运动超时保护
			//   - 刮板电机过载/堵转检测 → Step 90
			IF g_pass_count = 0 THEN
					scrape_Step := 40;
			ELSE

				A20_Scraper_collection_刮板收集();
				IF Scraper_collection_completed THEN
					刮板拍照工位站位符:=TRUE;
					scrape_gcode_instructions := '';  // 消费 G-code 指令
					Scraper_collection_completed:=FALSE;
					stepTimer(IN := FALSE, PT := T#0S);
					scrape_Step := 30;
				END_IF
			END_IF

		 30: // ═══ 机器人取粉末收集器 ═══
        // 对应 ref_plc_scraping.txt Step 30: Robot_material_retrieval_机器人取粉末收集器()
        // TODO【实机集成点】替换 stepTimer 为真实 FB 调用：
        //   Robot_material_retrieval_机器人取粉末收集器();
        //   等待 Robot_completes_material_retrieval = TRUE
        // TODO【逻辑判断】实机需判断：
        //   - 机器人到位传感器确认
        //   - 机器人抓取超时保护
        //   - 粉末收集器就位检测
			A30_Robot_material_retrieval_机器人取粉末收集器();
			IF Robot_completes_material_retrieval THEN
				stepTimer(IN := FALSE, PT := T#0S);
				scrape_IsLast := FALSE;   // ★ 新增：消费型变量子步内归零
				scrape_Done := TRUE;
				scrape_Busy := FALSE;
				Robot_completes_material_retrieval:=FALSE;
				scrape_Step := 0;
			END_IF

		90: // ═══ 故障态：等待外部 scrape_Reset 脉冲 ═══
			scrape_Error := TRUE;   // 故障态本身不动作，仅等待顶部复位逻辑

    END_CASE
END_IF

CASE 初始化step OF
	0:
		刮板拍照真空自动:=FALSE;
		刮板拍照真空手动:=FALSE;
		刮板拍照无刷电机手动:=FALSE;
		刮板拍照无刷电机自动:=FALSE;
		刮板拍照定位气缸手动:=FALSE;
		刮板拍照定位气缸自动:=FALSE;
		粉末收集器定位手动:=FALSE;
		粉末收集器定位自动:=FALSE;
		刮板拍照遮光气缸手动:=FALSE;
		刮板拍照遮光气缸自动:=FALSE;
		刮板拍照旋转气缸手动:=FALSE;
		刮板拍照旋转气缸自动:=FALSE;
		刮板拍照下压气缸手动:=FALSE;
		刮板拍照下压气缸自动:=FALSE;
		拍照工位允许放硅胶板:=FALSE;
		拍照工位允许放收集器:=FALSE;
		拍照工位机器人退出工位:=FALSE;
		拍照工位允许取收集器:=FALSE;
		拍照工位机器人退出:=FALSE;
		scrape_WaitConfirm := FALSE;
		 scrape_IsLast := FALSE;       // ★ 新增
		拍照工位放硅胶板完成 := FALSE;

		拍照工位机器人到达夹持位 := FALSE;

		拍照工位机器人退出工位完成 := FALSE;

		拍照工位机器人到达收集器夹持位 := FALSE;

		拍照工位机器人退出完成 := FALSE;
		拍照工位允许取硅胶板放废料区 := FALSE;
		拍照工位允许取硅胶板去展开 := FALSE;
		拍照工位机器人取硅胶板完成 := FALSE;
		拍照step:=0;
		机器人取物料step:=0;
		刮板收集step:=0;

		Camera_scraper_initialization_OK:=FALSE;
		Photo_preparation_completed_OK:=FALSE;
		Scraper_collection_completed:=FALSE;
		Robot_completes_material_retrieval:=FALSE;
		初始化step:=5;
	5:
		刮板轴10ZDATE.xMoveAbs:=FALSE;
		刮板轴9XDATE.xMoveAbs:=FALSE;
		拍照轴8YDATE.xMoveAbs:=FALSE;
		初始化step:=6;
	6:
		刮板轴10ZDATE.fAbsTarget:=0;
		刮板轴10ZDATE.xMoveAbs:=TRUE;
		IF 刮板轴10ZDATE.bAbMoveDone THEN
			刮板轴10ZDATE.xMoveAbs:=FALSE;
			初始化step:=10;
		END_IF
	10:
		刮板轴9XDATE.fAbsTarget:=335;
		刮板轴9XDATE.xMoveAbs:=TRUE;
		IF 刮板轴9XDATE.bAbMoveDone THEN
			刮板轴9XDATE.xMoveAbs:=FALSE;
			初始化step:=20;
		END_IF
	20:
		IF 刮板拍照遮光气缸上位 THEN
			拍照轴8YDATE.fAbsTarget:=0;
			拍照轴8YDATE.xMoveAbs:=TRUE;
			IF 拍照轴8YDATE.bAbMoveDone THEN
				拍照轴8YDATE.xMoveAbs:=FALSE;
				Camera_scraper_initialization_OK:=TRUE;
				初始化step:=0;
			END_IF	
		END_IF		

END_CASE

CASE 拍照step OF
	0:
		刮板轴9XDATE.fAbsTarget:=335;
		刮板轴9XDATE.xMoveAbs:=TRUE;
		IF 刮板轴9XDATE.bAbMoveDone THEN
			刮板轴9XDATE.xMoveAbs:=FALSE;
			IF scrape_PhotoMode=2 THEN
				scrape_WaitConfirm := TRUE;  // 标记送板完成
				拍照step:=10;
			ELSE
				拍照step:=1;
			END_IF
		END_IF

	1:
		拍照工位允许放硅胶板:=TRUE;
		IF 拍照工位放硅胶板完成 THEN
			拍照工位允许放硅胶板:=FALSE;
			拍照工位放硅胶板完成:=FALSE;
			刮板拍照定位气缸自动:=TRUE;
			IF scrape_PhotoMode=1 THEN
				拍照step:=30;
			ELSE 
				拍照step:=10;
			END_IF

		END_IF
	10:
		拍照工位允许放收集器:=TRUE;
		IF 拍照工位机器人到达夹持位 THEN
			拍照工位允许放收集器:=FALSE;
			刮板拍照下压气缸自动:=TRUE;
			拍照step:=20;
		END_IF
	20:
		TON_0(IN:=TRUE, PT:=T#1S , Q=> , ET=> );
		IF TON_0.Q THEN
			拍照工位机器人退出工位:=TRUE;
			IF 拍照工位机器人退出工位完成 THEN
				拍照工位机器人退出工位完成:=FALSE;
				拍照工位机器人退出工位:=FALSE;
				刮板拍照下压气缸自动:=TRUE;
				IF scrape_PhotoMode=2 THEN
					scrape_WaitConfirm := FALSE;
					Photo_preparation_completed_OK:=TRUE;
					拍照step:=0;
				ELSE
					拍照step:=30;
				END_IF

			END_IF
		END_IF
	30:
		IF 刮板拍照遮光气缸上位  THEN
			拍照轴8YDATE.fAbsTarget:=420;
			拍照轴8YDATE.xMoveAbs:=TRUE;
			IF 拍照轴8YDATE.bAbMoveDone THEN
				拍照轴8YDATE.xMoveAbs:=FALSE;
				刮板拍照遮光气缸自动:=TRUE;
				拍照step:=40;
			END_IF
		END_IF

	40:
		IF 刮板拍照遮光气缸下位 THEN
			scrape_WaitConfirm := TRUE;  // 标记送板完成

			拍照step:=50;
		END_IF
	50:
		IF confirmRisingEdge THEN
			刮板拍照遮光气缸自动:=FALSE;
			scrape_WaitConfirm := FALSE;
			拍照step:=60;
		END_IF
	60:
		IF 刮板拍照遮光气缸上位 THEN
			拍照轴8YDATE.fAbsTarget:=0;
			拍照轴8YDATE.xMoveAbs:=TRUE;
			IF 拍照轴8YDATE.bAbMoveDone THEN
				拍照轴8YDATE.xMoveAbs:=FALSE;
				Photo_preparation_completed_OK:=TRUE;
				拍照step:=0;
			END_IF
		END_IF








END_CASE

CASE 刮板收集step OF
	0:
		刮板拍照真空自动:=TRUE;
		//刮板拍照无刷电机自动:=TRUE;

		// 首次进入：初始化 k 与首 pass 的 Z
		IF k_pass = 0 THEN

			k_pass := 1;
			g_pass_z := g_plate_surface_z + g_total_depth / INT_TO_LREAL(g_pass_count);
		END_IF

		// 触发 CNC：bExe 直接拉高，PLC 侧已有的 SMC pipeline 自动执行
		 CNC启动:= TRUE;
		刮板收集step:=10;
		// 单 pass 完成 → 推进或退出

	10:
		IF CNC完成 THEN
			IF k_pass >= g_pass_count THEN
				CNC启动 := FALSE;
				k_pass := 0;
				刮板收集step:=20;
			ELSE
				k_pass := k_pass + 1;
				g_pass_z := g_plate_surface_z
						  + INT_TO_LREAL(k_pass) * g_total_depth
						  / INT_TO_LREAL(g_pass_count);
				 //Z轴高度计算   安全高度+刮取次数*总需要刮取的高速/需要刮取的次数
				CNC启动 := FALSE;   // 下个扫描周期上面 bExe := TRUE 形成上升沿，pipeline 重跑
				刮板收集step:=0;
			END_IF
		END_IF

	20:
		  IF scrape_IsLast THEN
				拍照工位允许取硅胶板放废料区:=TRUE;   // ★ 仅最后一次刮取后才允许送废料
				scrape_IsLast:=FALSE;
				scrape_PhotoMode:=0;
		  END_IF
		刮板拍照定位气缸自动:=FALSE;
		刮板拍照真空自动:=FALSE;
		刮板拍照无刷电机自动:=FALSE;
		CNC启动:=FALSE;
		刮板拍照旋转气缸自动:=TRUE;
		Scraper_collection_completed:=TRUE;
		刮板收集step:=0;
// 	30:
// 		IF 拍照工位机器人取硅胶板完成 THEN
// 			拍照工位允许取硅胶板:=FALSE;
// 			Scraper_collection_completed:=TRUE;
// 			刮板收集step:=0;
// 		END_IF








END_CASE

CASE 机器人取物料step OF
	0:
		拍照工位允许取收集器:=TRUE;
		IF 拍照工位机器人到达收集器夹持位 THEN
			拍照工位允许取收集器:=FALSE;
			刮板拍照下压气缸自动:=FALSE;
			机器人取物料step:=10;
		END_IF
	10:
		IF 刮板拍照下压气缸上位 THEN
			拍照工位机器人退出:=TRUE;
			机器人取物料step:=20;
		END_IF
	20:
		IF 拍照工位机器人退出完成 THEN
			拍照工位机器人退出:=FALSE;
			刮板拍照旋转气缸自动:=FALSE;
			拍照工位机器人退出完成:=FALSE;
			机器人取物料step:=30;
			IF scrape_IsLast THEN

				机器人取物料step:=30;                    // ★ 最后一次：去 step 30 清板
			ELSE
				Robot_completes_material_retrieval:=TRUE; // ★ 中间：直接 Done，不清板
				机器人取物料step:=0;
			END_IF
		END_IF
	30:
		IF 拍照工位机器人取硅胶板完成 THEN
			拍照工位允许取硅胶板放废料区:=FALSE;
			拍照工位机器人取硅胶板完成:=FALSE;
			Robot_completes_material_retrieval:=TRUE;
			机器人取物料step:=0;
		END_IF	
END_CASE
